import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import "../Styles/UserProfile.css";

import { useForm } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import { bankCardSchema } from "../Validations/Bank";

const CompanyProfile = () => {
  const navigate = useNavigate();

  const [company, setCompany] = useState({});
  const [preview, setPreview] = useState(null);
  const [showCardModal, setShowCardModal] = useState(false);

  const [selectedBank, setSelectedBank] = useState("");
  const [cardNumber, setCardNumber] = useState("");
  const [cardName, setCardName] = useState("");
  const [expiry, setExpiry] = useState("");
  const [cvv, setCvv] = useState("");

  const {
    register,
    handleSubmit,
    formState: { errors },
    reset,
  } = useForm({
    resolver: yupResolver(bankCardSchema),
  });

  // LOAD COMPANY
  useEffect(() => {
    const saved = JSON.parse(localStorage.getItem("loggedUser"));
    if (!saved?.email) {
      navigate("/login");
      return;
    }

    axios
      .get(`http://localhost:3001/company/${saved.email}`)
      .then((res) => {
        setCompany(res.data);

        setSelectedBank(res.data.bankName || "");
        setCardNumber(res.data.cardNumber || "");
        setCardName(res.data.cardName || "");
        setExpiry(res.data.expiry || "");
        setCvv(res.data.cvv || "");

        reset({
          selectedBank: res.data.bankName || "",
          cardNumber: res.data.cardNumber || "",
          cardName: res.data.cardName || "",
          expiry: res.data.expiry || "",
          cvv: res.data.cvv || "",
        });
      })
      .catch(() => alert("Load failed"));
  }, [navigate, reset]);

  // SAVE BANK
  const saveCardInfo = async () => {
    try {
      await axios.put("http://localhost:3001/company/updateBank", {
        email: company.email,
        bankName: selectedBank,
        cardNumber,
        cardName,
        expiry,
        cvv,
      });

      setCompany((prev) => ({
        ...prev,
        bankName: selectedBank,
        cardNumber,
        cardName,
        expiry,
        cvv,
      }));

      alert("Bank info saved!");
      setShowCardModal(false);
    } catch {
      alert("Failed to save bank");
    }
  };

  // DELETE BANK
  const deleteBank = async () => {
    if (!window.confirm("Delete bank info?")) return;

    try {
      await axios.put("http://localhost:3001/company/deleteBankCard", {
        email: company.email,
      });

      setSelectedBank("");
      setCardNumber("");
      setCardName("");
      setExpiry("");
      setCvv("");

      setCompany((prev) => ({
        ...prev,
        bankName: "",
        cardNumber: "",
        cardName: "",
        expiry: "",
        cvv: "",
      }));

      reset();
      alert("Deleted");
    } catch {
      alert("Error deleting");
    }
  };

  // PROFILE IMAGE
  const handleImageUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const form = new FormData();
    form.append("file", file);
    form.append("email", company.email);
    form.append("type", "profile");

    try {
      const res = await axios.post(
        "http://localhost:3001/uploadCompanyFile",
        form,
        { headers: { "Content-Type": "multipart/form-data" } }
      );

      setPreview(res.data.fileUrl);
      setCompany((prev) => ({
        ...prev,
        profileImage: res.data.fileUrl,
      }));
    } catch {
      alert("Upload failed");
    }
  };

  // LICENSE UPLOAD
  const handleLicenseUpload = async (e) => {
    const f = e.target.files[0];
    if (!f) return;

    const form = new FormData();
    form.append("file", f);
    form.append("email", company.email);
    form.append("type", "license");

    try {
      const res = await axios.post(
        "http://localhost:3001/uploadCompanyFile",
        form,
        { headers: { "Content-Type": "multipart/form-data" } }
      );

      setCompany((prev) => ({ ...prev, licenseFile: res.data.fileUrl }));
    } catch {
      alert("Failed");
    }
  };

  // DELETE LICENSE
  const deleteLicense = async () => {
    if (!window.confirm("Delete license?")) return;

    try {
      await axios.put("http://localhost:3001/company/deleteLicense", {
        email: company.email,
      });

      setCompany((p) => ({ ...p, licenseFile: "" }));
    } catch {
      alert("Delete failed");
    }
  };

  return (
    <div className="profile-page">
      {/* PROFILE HEADER */}
      <div className="profile-card">
        <div className="profile-left">
          <div className="profile-img-container">
            <img
              src={
                preview ||
                company.profileImage ||
                "https://cdn-icons-png.flaticon.com/512/3135/3135768.png"
              }
              className="profile-img"
            />
            <label htmlFor="companyImg" className="upload-circle-C">
              📷
            </label>
            <input
              type="file"
              id="companyImg"
              accept="image/*"
              style={{ display: "none" }}
              onChange={handleImageUpload}
            />
          </div>

          <div>
            <h2 className="profile-name">{company.companyName}</h2>
            <p className="profile-email">{company.email}</p>
            <p className="profile-detail">
              {company.industry} • {company.location}
            </p>
          </div>
        </div>
      </div>

      {/* LICENSE SECTION */}
      <div className="payment-box">
        <h3>Business License</h3>

        {company.licenseFile ? (
          <div className="cv-section">
            <p className="cv-success">License Uploaded Successfully</p>

            <div className="cv-actions">
              <a
                href={company.licenseFile}
                target="_blank"
                className="cv-btn view"
              >
                View
              </a>

              <label htmlFor="licenseUpload" className="cv-btn replace">
                Replace
              </label>

              <button className="cv-btn delete" onClick={deleteLicense}>
                Delete
              </button>
            </div>

            <input
              id="licenseUpload"
              type="file"
              accept=".pdf"
              style={{ display: "none" }}
              onChange={handleLicenseUpload}
            />
          </div>
        ) : (
          <>
            <input
              id="licenseUpload"
              type="file"
              accept=".pdf"
              style={{ display: "none" }}
              onChange={handleLicenseUpload}
            />
            <label className="upload-cv-btn" htmlFor="licenseUpload">
              Upload License (PDF)
            </label>
          </>
        )}
      </div>

      {/* BANK CARD */}
      <div className="payment-box">
        <h3>Bank / Benefit Card</h3>

        <div className="card-preview">
          <div className="bank-card">
            <div className="bank-chip"></div>

            <p className="card-number">
              {company.cardNumber || "XXXX XXXX XXXX XXXX"}
            </p>

            <p className="card-holder">{company.cardName || "Card Holder"}</p>

            <p className="bank-name-preview">
              {company.bankName || "No Bank Selected"}
            </p>
          </div>
        </div>

        <div className="card-buttons">
          {!company.cardNumber ? (
            <button
              className="add-card-btn"
              onClick={() => setShowCardModal(true)}
            >
              + Add Card
            </button>
          ) : (
            <>
              <button
                className="edit-card-btn"
                onClick={() => setShowCardModal(true)}
              >
                Edit Card
              </button>
              <button className="delete-card-btn" onClick={deleteBank}>
                Delete Card
              </button>
            </>
          )}
        </div>
      </div>

      {/* MODAL — EDIT CARD */}
      {showCardModal && (
        <div className="modal-overlay">
          <div className="modal-box">
            <div className="modal-header">
              <h3>Edit Card</h3>
              <button
                className="close-btn"
                onClick={() => setShowCardModal(false)}
              >
                ×
              </button>
            </div>

            <label>Select Bank</label>
            <div className="bank-radio-row">
              <label>
                <input
                  type="radio"
                  value="Bank Muscat"
                  {...register("selectedBank")}
                  checked={selectedBank === "Bank Muscat"}
                  onChange={(e) => setSelectedBank(e.target.value)}
                />
                Bank Muscat
              </label>

              <label>
                <input
                  type="radio"
                  value="Bank Dhofar"
                  {...register("selectedBank")}
                  checked={selectedBank === "Bank Dhofar"}
                  onChange={(e) => setSelectedBank(e.target.value)}
                />
                Bank Dhofar
              </label>

              <label>
                <input
                  type="radio"
                  value="NBO"
                  {...register("selectedBank")}
                  checked={selectedBank === "NBO"}
                  onChange={(e) => setSelectedBank(e.target.value)}
                />
                NBO
              </label>
            </div>
            <p className="error">{errors.selectedBank?.message}</p>

            <label>Card Number</label>
            <input
              className="modal-input"
              {...register("cardNumber")}
              value={cardNumber}
              onChange={(e) => {
                let v = e.target.value.replace(/\D/g, "");
                v = v.match(/.{1,4}/g)?.join(" ") || v;
                setCardNumber(v);
              }}
            />
            <p className="error">{errors.cardNumber?.message}</p>

            <label>Cardholder Name</label>
            <input
              className="modal-input"
              {...register("cardName")}
              value={cardName}
              onChange={(e) => setCardName(e.target.value)}
            />
            <p className="error">{errors.cardName?.message}</p>

            <label>Expiration Date</label>
            <input
              type="month"
              className="modal-input"
              {...register("expiry")}
              value={expiry}
              onChange={(e) => setExpiry(e.target.value)}
            />
            <p className="error">{errors.expiry?.message}</p>

            <label>CVV</label>
            <input
              type="password"
              maxLength="4"
              className="modal-input"
              {...register("cvv")}
              value={cvv}
              onChange={(e) => setCvv(e.target.value)}
            />
            <p className="error">{errors.cvv?.message}</p>

            <div className="modal-buttons">
              <button className="save-btn" onClick={handleSubmit(saveCardInfo)}>
                Save
              </button>

              <button className="clear-btn" onClick={() => reset()}>
                Clear
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CompanyProfile;
